describe('Login Password Mistyping - Error State', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should display clear failure message when password is mistyped', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginAttempt');

    // Fill in the username
    cy.get('[data-testid="username-input"]').type('tomsmith');

    // Fill in the wrong password
    cy.get('[data-testid="password-input"]').type('wrongpassword');

    // Submit the form
    cy.get('[data-testid="login-button"]').click();

    // Verify we are still on the login page
    cy.url().should('include', '/login');

    // Verify the error flash banner is visible
    cy.get('[data-testid="flash-error"]').should('be.visible');

    // Verify the error message contains the expected text
    cy.get('[data-testid="flash-error"]').should('contain', 'Your password is invalid!');

    // Verify the error message is styled appropriately
    cy.get('[data-testid="flash-error"]').should('have.class', 'flash-error');

    // Verify the form is still intact and ready for another attempt
    cy.get('[data-testid="username-input"]').should('have.value', 'tomsmith');
    cy.get('[data-testid="password-input"]').should('have.value', 'wrongpassword');
  });

  it('should not display error message when password is correct', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginAttempt');

    // Fill in the username
    cy.get('[data-testid="username-input"]').type('tomsmith');

    // Fill in the correct password
    cy.get('[data-testid="password-input"]').type('correctpassword123');

    // Submit the form
    cy.get('[data-testid="login-button"]').click();

    // Verify we are redirected to the dashboard
    cy.url().should('include', '/dashboard');

    // Verify the error flash banner is not visible
    cy.get('[data-testid="flash-error"]').should('not.exist');

    // Verify the success message is displayed instead
    cy.get('[data-testid="flash-success"]').should('be.visible');
    cy.get('[data-testid="flash-success"]').should('contain', 'Login successful');
  });
});
